insert into public.academy_knowledge(slug,title,domain,content,status,source_label) values
('academy-salary-dialogue','Prétentions salariales : cadrer la peur avant le chiffre','salaire négociation entretien','En entretien, clarifier d’abord si le candidat redoute le rejet ou la sous-évaluation. Ensuite, expliquer les critères d’une fourchette contextualisée et le package global. Ne pas inventer de salaire marché ni exiger un montant exact prématurément.','approved','Dialogue de référence interne n°1, propriétaire du produit'),
('academy-oral-fillers','Communication orale : tics et pauses','communication entretien oral','Face aux répétitions écrites du type bah, genre, du coup, inviter à ralentir et à pratiquer des pauses. Ne jamais prétendre avoir mesuré des hésitations vocales ou une durée sans audio analysé.','approved','Dialogue de référence interne n°3, propriétaire du produit'),
('academy-authentic-weakness','Défaut professionnel : sortir des réponses convenues','entretien RH qualités défauts','Au lieu de réciter « trop perfectionniste », faire identifier une difficulté opérationnelle réelle, ses impacts et une action corrective. Favoriser les exemples sincères, sans jugement personnel.','approved','Dialogue de référence interne n°4, propriétaire du produit'),
('academy-product-leadership','Leadership : arbitrages et décisions','head of product management leadership','Ne pas confondre leadership et taille d’équipe. Pour un Head of Product ayant managé trois collaborateurs, chercher les preuves de priorisation, décisions difficiles, alignement des parties prenantes et résultats observables.','approved','Dialogue de référence interne n°5, propriétaire du produit'),
('academy-conflict-example','Conflit : passer du principe à la situation vécue','conflit communication gestion équipe','Si un candidat évoque seulement l’écoute active et la communication non violente, l’inviter à raconter un conflit vécu, sa première phrase et les effets de son intervention avant de recommander STAR.','approved','Dialogue de référence interne n°7, propriétaire du produit'),
('academy-failure-ownership','Échec : responsabilité et apprentissage','échec projet entretien','Lorsqu’un retard est attribué à un prestataire, explorer sans jugement les leviers d’anticipation, la capacité d’action réelle, les jalons intermédiaires et les enseignements. Ne pas lui attribuer automatiquement une faute.','approved','Dialogue de référence interne n°9, propriétaire du produit'),
('academy-end-interview','Questions à poser en fin d’entretien','fin entretien questions recruteur','Au lieu de dire que tout est clair, proposer une question contextualisée sur les défis des 90 premiers jours, les critères de réussite ou les objectifs du poste à six mois.','approved','Dialogue de référence interne n°10, propriétaire du produit')
